/* Generated by services/_build.py from services/_faq.py. The AI assistant uses it as its fallback knowledge. */
window.HC_FAQ = [{"q": "Hvordan booker jeg en tid hos Hot Cut?", "a": "Du booker online døgnet rundt via vores booking, eller ringer på 97 12 60 60. Skal du have klip og farve samme dag, så book i god tid, så vi kan afsætte nok tid."}, {"q": "Kan jeg booke online uden for åbningstid?", "a": "Ja. Online bookingen er åben døgnet rundt, også om aftenen og i weekenden, hvor salonen er lukket."}, {"q": "Hvordan flytter eller aflyser jeg min tid?", "a": "Ring på 97 12 60 60 eller skriv til info@hotcut.dk så tidligt som muligt. Så kan vi give tiden til en anden og finde en ny tid til dig."}, {"q": "Kan jeg få en tid samme dag?", "a": "Se ledige tider i online bookingen, eller ring på 97 12 60 60, så hjælper vi dig med den første ledige tid."}, {"q": "Hvor lang tid i forvejen skal jeg booke?", "a": "Til en almindelig klipning kan du ofte få en tid inden for kort tid. Til større farvebehandlinger, extensions og opsætning til bryllup eller konfirmation anbefaler vi at booke i god tid, især i højsæsonen om foråret og sommeren."}, {"q": "Kan jeg booke tid til flere personer på én gang?", "a": "Ja. Ring på 97 12 60 60, så finder vi tider, der passer sammen, fx til en mor og et barn eller til brud og brudepiger."}, {"q": "Kan jeg få en gratis konsultation før jeg booker?", "a": "Ja. Du er altid velkommen til en uforpligtende snak i salonen, og til extensions starter vi altid med en gratis konsultation, hvor du får en konkret pris."}, {"q": "Hvad koster en dameklip i Herning hos Hot Cut?", "a": "En dameklip inkl. vask og føn koster 520 kr. Pandehår koster 89 kr, og en luksus hårkur med hovedbundsmassage kan tilvælges for 159 kr."}, {"q": "Hvad koster en herreklip?", "a": "En herreklip koster 370 kr. Herreklip krans koster 310 kr, maskinklip 200 kr og trimning af skæg 150 kr."}, {"q": "Hvorfor koster en dameklip mere end en herreklip?", "a": "En dameklip kræver typisk længere behandlingstid, mere detaljeret klippeteknik og grundigere styling. Prisen er inkl. vask og føn."}, {"q": "Hvad koster det at få farvet hår?", "a": "Helfarve koster 650 kr på kort hår, 1.050 kr på mellemlangt hår og 1.200 kr på langt hår. Bundfarve koster 650 kr (750 kr på langt hår). Farve på mellemlangt og langt hår er inkl. Olaplex."}, {"q": "Hvad koster reflekser?", "a": "Reflekser med stanniol koster 800 kr på kort hår, 1.200 kr på mellemlangt og 1.400 kr på langt hår. Reflekser over skilning koster 950 kr, reflekser med hætte 800 kr, og helfarve med reflekser 800–1.600 kr."}, {"q": "Er priserne inkl. moms?", "a": "Ja. Alle priser er inkl. moms."}, {"q": "Koster rådgivningen noget?", "a": "Nej. Rådgivning er gratis og en del af hver behandling."}, {"q": "Får jeg rådgivning, før I går i gang?", "a": "Ja, altid og gratis. Vi tager udgangspunkt i din ansigtsform, hårtype og stil, og du er velkommen til at medbringe inspirationsbilleder."}, {"q": "Hvor ofte skal jeg have klippet mit hår?", "a": "Generelt anbefaler vi en klipning hver 6.–8. uge. Har du langt hår og vil bevare længden, kan du vente op til 12 uger. En fade skal ofte vedligeholdes lidt oftere."}, {"q": "Kan I klippe krøllet og bølget hår?", "a": "Ja. Vi tilpasser klipningen til dit naturlige fald, uanset om håret er glat, bølget eller krøllet, så frisuren er flot både stylet og naturligt."}, {"q": "Hvordan ved jeg, om kort eller langt hår klæder mig?", "a": "Det afhænger af din ansigtsform, din hårtekstur og hvor meget tid du vil bruge på styling. Vi hjælper dig med at vælge ud fra din stil og hverdag."}, {"q": "Kan jeg tage et billede med af den frisure, jeg ønsker?", "a": "Ja, gerne. Et billede er en god start, og vi tilpasser looket til dit hår, så det også fungerer derhjemme."}, {"q": "Vasker og føner I håret ved en dameklip?", "a": "Ja. En dameklip hos os er inkl. vask og føn, og vi viser dig, hvordan du selv styler håret."}, {"q": "Hvad er en luksus hårkur?", "a": "Det er en plejende hårkur med hovedbundsmassage, som du kan tilvælge, når du bliver klippet. Den koster 159 kr."}, {"q": "Klipper I pandehår separat?", "a": "Ja. Pandehår koster 89 kr."}, {"q": "Hvilke herreklip laver I?", "a": "Alt fra klassisk sideskilning og crew cut til fade, textured crop og undercut. Lige nu er skin fade, mellemlang fade og den klassiske slick back blandt de mest populære."}, {"q": "Hvilken herrefrisure passer til mit ansigt?", "a": "En fade eller crew cut giver definition til et rundt ansigt, mens en klassisk sideskilning eller længere hår med tekstur ofte passer til et firkantet ansigt. Har du tyndt hår, får et kort klip håret til at se fyldigere ud."}, {"q": "Trimmer I skæg?", "a": "Ja. Trimning af skæg koster 150 kr og kan bookes sammen med en herreklip. Vi trimmer, så skægget passer til din ansigtsform og frisure."}, {"q": "Kan mænd få farve?", "a": "Ja. Vi har en hurtig 10 minutters farve til herrer for 250 kr, og vi laver også almindelige farvebehandlinger."}, {"q": "Klipper I børn, og hvad koster det?", "a": "Ja. Børneklip koster 240 kr (0–3 år) og 290 kr (4–8 år). Pigeklip 9–12 år koster 390 kr og drengeklip 9–12 år 310 kr."}, {"q": "Klipper I både damer, herrer og børn?", "a": "Ja. Dørene er åbne for alle, uanset køn, alder eller stil."}, {"q": "Hvad koster balayage hos Hot Cut?", "a": "Balayage koster 1.450 kr og 1.900 kr med eftertoning, begge inkl. Olaplex."}, {"q": "Hvad er balayage?", "a": "En farveteknik, hvor håret lysnes med bløde overgange, så farven smelter sammen med din egen. Det giver et naturligt, solkysset look og en blødere udgroning."}, {"q": "Hvad er forskellen på balayage og babylights?", "a": "Balayage giver et blødt, naturligt farvespil med mindre markant udgroning. Babylights er meget fine lyse striber, der giver et mere detaljeret, lyst spil. Babylights koster 1.800 kr (2.250 kr med eftertoning)."}, {"q": "Hvad er forskellen på bundfarve, helfarve og reflekser?", "a": "Bundfarve farver kun udgroningen ved hovedbunden. Helfarve giver en ensartet farve i hele håret. Reflekser lysner eller mørkner udvalgte stråler, så håret får dybde og spil."}, {"q": "Hvad er eftertoning, og har jeg brug for det?", "a": "Eftertoning justerer tonen efter lysningen, så resultatet bliver koldere, varmere, mere beige eller mere naturligt. Om du har brug for det, afhænger af dit hår og den nuance, du ønsker."}, {"q": "Hvor lang tid tager en farvebehandling?", "a": "Det afhænger af behandlingen og hårets længde, tykkelse og udgangspunkt. En balayage tager typisk længere tid end en almindelig farve. Ring gerne, hvis du skal kende tiden præcist."}, {"q": "Hvor ofte skal jeg have farvet håret?", "a": "Det afhænger af teknikken. En helfarve eller bundfarve skal ofte opfriskes, når udgroningen bliver synlig, mens balayage og bløde reflekser vokser pænere ud og kan holde længere mellem besøgene. Vi rådgiver dig om, hvad der passer til dit hår."}, {"q": "Kan I dække grå hår?", "a": "Ja. Grå hår kan dækkes med bundfarve eller helfarve, eller blødes op med reflekser, så udgroningen bliver mindre synlig. Vi finder løsningen sammen med dig."}, {"q": "Hvilken hårfarve bruger I?", "a": "Vi farver med idHAIR, et dansk mærke med professionelle hårfarver: Hair Paint (permanent farve), Gloss (demi-permanent toner til toning og glans) og Colour Bomb (farvebalsam til pleje mellem besøgene)."}, {"q": "Hvad er Olaplex, og er det med i prisen?", "a": "Olaplex genopbygger de bindinger i håret, som farvning, varme og sol bryder ned. Det er inkluderet i farve på mellemlangt og langt hår samt i balayage og babylights."}, {"q": "Kan jeg få klip og farve i samme besøg?", "a": "Ja. Mange kombinerer en dameklip med farve, balayage eller reflekser. Book i god tid, så vi kan afsætte den nødvendige tid."}, {"q": "Hvad er årets hårfarver i 2026?", "a": "Varme blonde nuancer, kobber og bløde overgange. Skarpe striber og kolde asketoner træder et skridt tilbage. Læs mere i vores blogindlæg om hårfarver 2026."}, {"q": "Hvad gør jeg, hvis jeg har reageret på hårfarve før?", "a": "Fortæl os det, når du booker eller ringer, så frisøren kan tale med dig om det inden behandlingen. Er du i tvivl om en allergi, så spørg din læge."}, {"q": "Tilbyder I keratinbehandling, og hvad koster det?", "a": "Ja. Keratinbehandling koster 2.000 kr på mellemlangt hår og 2.800 kr på langt hår."}, {"q": "Laver I permanent?", "a": "Ja. Permanent inkl. klip koster 1.400 kr på kort hår, 1.500 kr på mellemlangt og 1.600 kr på langt hår."}, {"q": "Hvordan passer jeg bedst på farvet hår?", "a": "Brug shampoo og balsam til farvet hår, beskyt håret mod varme og udtørring, og følg frisørens råd om, hvornår farven skal opfriskes. En farvebalsam som idHAIR Colour Bomb holder farven frisk mellem besøgene."}, {"q": "Hvad gør jeg ved slidt eller tørt hår?", "a": "Klip spidserne jævnligt, brug varmebeskyttelse, og giv håret en kur. Olaplex No.3 er en kur, der genopbygger håret, og vi rådgiver gerne om den rette pleje. En hår- og hovedbundsanalyse kan vise, hvad dit hår har brug for."}, {"q": "Hvordan undgår jeg gule toner i lyst hår?", "a": "Brug en lilla toningsshampoo som Olaplex No.4P Blonde Enhancer, der fjerner gule og messingagtige toner. En eftertoning i salonen kan også justere tonen."}, {"q": "Skal jeg bruge varmebeskyttelse?", "a": "Ja, når du bruger føntørrer, glattejern eller krøllejern. Det beskytter håret mod udtørring og slid."}, {"q": "Hvad koster extensions hos Hot Cut?", "a": "Extensions starter fra 3.600 kr. Prisen afhænger af mængde og længde, og du får en konkret pris ved en gratis konsultation."}, {"q": "Hvilke extensions bruger I?", "a": "Vi bruger Hairtalk tape extensions af 100 % ægte Remy-hår i længder fra 25 til 55 cm. Fæsterne lægges fladt ind mod hovedet, og der bruges ikke varme ved påsætningen."}, {"q": "Hvor længe holder tape extensions?", "a": "Tape extensions skal typisk rykkes op efter 6–8 uger, fordi dit eget hår vokser. Selve extensionshåret kan ofte genbruges flere gange, hvis det plejes korrekt."}, {"q": "Kan tape extensions skade mit eget hår?", "a": "Ikke når de sættes korrekt i og vedligeholdes. For meget ekstra hår, forkert placerede fæster eller for sen oprykning kan belaste håret, og derfor vurderer vi dit hår først."}, {"q": "Passer extensions til fint hår?", "a": "Ja, tape extensions kan også bruges i fint hår, fordi de er ultratynde. Mængden af hår og placeringen af fæsterne skal passe til dit eget hår, og det vurderer vi ved konsultationen."}, {"q": "Hvordan plejer jeg mine extensions?", "a": "Børst forsigtigt, brug produkter til extensions, kom balsam og olie i længderne og ikke på fæsterne, og tør håret grundigt ved fæsterne efter vask."}, {"q": "Kan jeg style og farve mine extensions?", "a": "Du kan style med føntørrer, glattejern og krøllejern, hvis du bruger varmebeskyttelse og undgår direkte varme på fæsterne. Hairtalk fraråder permanent farvning og lysning, så vi finder den rette nuance inden påsætning."}, {"q": "Har I extensions, jeg selv kan tage af?", "a": "Ja. Hairtalk Hairband er ægte hår på et usynligt, elastisk bånd uden lim, tape eller clips. Det tager under fem minutter at sætte på, og du tager det selv af igen. Clip-on extensions er også en mulighed."}, {"q": "Laver I opsætning til bryllup og konfirmation?", "a": "Ja. Brudeopsætning koster 1.600 kr, konfirmationsopsætning 750 kr og håropsætning 500 eller 750 kr."}, {"q": "Skal jeg have en prøveopsætning før brylluppet?", "a": "Vi anbefaler det. En prøveopsætning koster 500 kr, og så finder vi looket sammen, før dagen oprinder."}, {"q": "Hvornår skal jeg booke opsætning til bryllup eller konfirmation?", "a": "I god tid, især hvis dagen ligger i den travle sæson om foråret eller sommeren. Book gerne prøveopsætningen samtidig."}, {"q": "Hvad skal jeg tage med til en prøveopsætning?", "a": "Billeder af kjolen, pynten og din inspiration. Har du hårpynt eller blomster, så tag dem med."}, {"q": "Kan jeg få makeup samme dag som opsætningen?", "a": "Ja. Makeup koster 300 eller 600 kr og kan kombineres med opsætningen, så hår og makeup hænger sammen."}, {"q": "Kan gommen også blive klippet hos jer?", "a": "Ja. Gommen kan få herreklip (370 kr) og skægtrimning (150 kr) samme sted. Bliv gerne klippet en til to uger før brylluppet, så klippet når at falde på plads."}, {"q": "Hvad er bryllupsfrisurerne i 2026?", "a": "Blødere opsætninger, løse lokker, glansfulde bølger og friske blomster. Gommen går fra stiv voks til naturlig tekstur. Læs mere i vores blogindlæg om bryllupsfrisurer 2026."}, {"q": "Farver og retter I bryn og vipper?", "a": "Ja. Bryn rettet (voks eller pincet) koster 100 kr, bryn farvet 100 kr, vipper farvet 150 kr, og pakken med bryn og vipper farvet og rettet koster 300 kr."}, {"q": "Tilbyder I browlamination?", "a": "Ja. Browlift/browlamination koster 450 kr uden farve og 500 kr med farve."}, {"q": "Tilbyder I lash lift?", "a": "Ja, lash lift tilbydes også. Ring på 97 12 60 60 for at høre prisen."}, {"q": "Hvad koster makeup?", "a": "Makeup koster 300 kr (lille) eller 600 kr (stor)."}, {"q": "Sælger I vippe- og brynserum?", "a": "Ja. Vi forhandler Sanzi Beauty, et dansk mærke med vippe- og brynserum, mascara, læbeprodukter og pudder. De første resultater med vippeserummet ses typisk efter 6–8 uger."}, {"q": "Hvad er en hår- og hovedbundsanalyse?", "a": "Med vores analyseudstyr kigger vi helt tæt på din hovedbund og dine hårstrå. Et håndholdt kamera med kraftig forstørrelse viser dem på en skærm, så du selv kan se dem. Bagefter forklarer frisøren, hvad vi ser, og du får konkrete råd."}, {"q": "Hvad koster en håranalyse?", "a": "En hår- og hovedbundsanalyse koster 100 kr. Køber du produkter for 400 kr, trækkes de 100 kr fra, så analysen i praksis giver dig 25 % rabat på produkterne."}, {"q": "Hvem har gavn af en håranalyse?", "a": "Alle, der er i tvivl om, hvilke produkter og hvilken pleje deres hår og hovedbund har brug for, fx ved tørt, fedtet eller slidt hår."}, {"q": "Kan analysen kombineres med en klipning?", "a": "Ja. Du kan få analysen i forbindelse med dit næste besøg."}, {"q": "Er håranalysen en lægeundersøgelse?", "a": "Nej. Analysen giver råd om pleje og produkter. Har du hårtab, kløe eller andre gener, der bekymrer dig, så tal med din læge."}, {"q": "Hvilke mærker bruger og sælger I?", "a": "Olaplex, Roze Avenue, Sanzi Beauty, Hairtalk, ghd og idHAIR."}, {"q": "Hvilke Olaplex-produkter har I?", "a": "Blandt andet No.3 Hair Perfector (kur), No.4 Bond Maintenance shampoo, No.4P Blonde Enhancer til lyst hår, No.4C rensende shampoo og olien. Spørg i salonen, hvad der passer til dit hår."}, {"q": "Sælger I glattejern og føntørrere?", "a": "Ja. Vi har ghd-stylingværktøj på produktvæggen i salonen og hjælper gerne med at vælge det rigtige til dit hår."}, {"q": "Hvad er Roze Avenue?", "a": "Et nordisk hår- og skønhedsmærke skabt af stylister. Hos os finder du blandt andet tørshampoo, hårmasken Luxury Restore Masq og selvbruneren fra Glow Collection."}, {"q": "Kan jeg købe produkter uden at have en tid?", "a": "Ja, du er velkommen til at kigge forbi salonen i åbningstiden og få råd om produkterne."}, {"q": "Hvordan får jeg rabat på produkter?", "a": "Få en hår- og hovedbundsanalyse til 100 kr. Køber du produkter for 400 kr, trækkes de 100 kr fra."}, {"q": "Hvor ligger Hot Cut i Herning?", "a": "På Søndergade 12, 7400 Herning, centralt i byen. Det er nemt at kombinere dit besøg med en tur i gågaden."}, {"q": "Hvad er jeres åbningstider?", "a": "Mandag 09:00–15:00, tirsdag, onsdag og fredag 08:30–17:00 og torsdag 08:30–19:00. Lørdag og søndag er lukket. Online booking er åben døgnet rundt."}, {"q": "Har I åbent om aftenen?", "a": "Torsdag har vi åbent til kl. 19:00. De andre hverdage lukker vi kl. 17:00, mandag kl. 15:00."}, {"q": "Hvor kan jeg parkere?", "a": "Der er kantparkering langs Søndergade, som du kører ad hen til salonen, og en stor p-plads lige rundt om hjørnet ved Herning Bibliotek og biografen. Banegårdens P-kælder ligger også få minutters gang væk. Se kortet på kontaktsiden, og tjek skiltningen for tidsbegrænsning."}, {"q": "Hvordan kontakter jeg jer?", "a": "Ring på 97 12 60 60, skriv til info@hotcut.dk, eller skriv til os på Instagram @hotcutherning eller Facebook."}, {"q": "Hvem er frisørerne hos Hot Cut?", "a": "Heidi Møller (frisør og indehaver), Anna Sand Daasbjerg og Karina Andreasen. Kunderne roser især, at de bliver husket fra gang til gang."}, {"q": "Hvad siger kunderne om Hot Cut?", "a": "Hot Cut har 4,6 stjerner baseret på 69 anmeldelser på Google. Kunderne fremhæver især venlig betjening, ærlig rådgivning og at de bliver husket."}, {"q": "Hvad gør jeg, hvis jeg ikke er tilfreds?", "a": "Kontakt os hurtigst muligt på 97 12 60 60 eller info@hotcut.dk, så finder vi en løsning sammen."}, {"q": "Hvad kan AI-assistenten hjælpe med?", "a": "Den svarer døgnet rundt på spørgsmål om priser, behandlinger, åbningstider, extensions, farve, produkter og håranalyse, på dansk og engelsk. Du kan også stille spørgsmål med stemmen."}, {"q": "Kan AI-assistenten booke en tid for mig?", "a": "Nej. Den kan ikke se kalenderen, så selve bookingen foregår online eller på telefon 97 12 60 60."}, {"q": "Gemmer I det, jeg skriver til AI-assistenten?", "a": "Nej. Assistenten kører i din browser, og dine spørgsmål sendes ikke til os. Læs mere i vores privatlivspolitik."}, {"q": "Findes hjemmesiden på engelsk?", "a": "Ja. Hele hjemmesiden findes på dansk og engelsk. Skift sprog med DA/EN øverst på siden."}];
